import time, datetime, re

EPOCH = datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)

def _local_tz_for_epoch(sec):
    # Use local timezone as determined by system
    try:
        dt_utc = datetime.datetime.fromtimestamp(sec, tz=datetime.timezone.utc)
        local = dt_utc.astimezone()  # system local
        return local.tzinfo, local.utcoffset(), local.tzname()
    except Exception:
        return datetime.timezone.utc, datetime.timedelta(0), "UTC"

class TimeValue:
    __slots__=("epoch_ns","offset_sec","zone_name")
    def __init__(self, epoch_ns=0, offset_sec=0, zone_name="UTC"):
        self.epoch_ns=int(epoch_ns)
        self.offset_sec=int(offset_sec)
        self.zone_name=zone_name or "UTC"
    @staticmethod
    def now():
        ns=time.time_ns()
        sec=ns//1_000_000_000
        _, off, name = _local_tz_for_epoch(sec)
        off_sec=int(off.total_seconds()) if off else 0
        # If local is UTC, zone name UTC
        return TimeValue(ns, off_sec, name)
    @staticmethod
    def from_epoch_ns(ns, local=True):
        sec=int(ns)//1_000_000_000
        if local:
            _, off, name=_local_tz_for_epoch(sec)
            off_sec=int(off.total_seconds()) if off else 0
            return TimeValue(ns, off_sec, name)
        return TimeValue(ns,0,"UTC")
    @staticmethod
    def from_datetime(dt):
        # dt aware or naive (assume local)
        if dt.tzinfo is None:
            # interpret as local time wall clock: convert
            local = dt.astimezone() if False else None
            # Use mktime for wall time
            epoch_sec = time.mktime(dt.timetuple()) + dt.microsecond/1e6
            ns=int(round(epoch_sec*1e9))
            _, off, name=_local_tz_for_epoch(int(epoch_sec))
            return TimeValue(ns, int(off.total_seconds()) if off else 0, name)
        epoch_sec=dt.timestamp()
        ns=int(round(epoch_sec*1_000_000_000))
        off=dt.utcoffset(); zone=dt.tzname() or "UTC"
        off_sec=int(off.total_seconds()) if off else 0
        # For unnamed offset zones, Go uses +HHMM as zone name
        if dt.tzinfo is datetime.timezone.utc:
            zone="UTC"
        return TimeValue(ns, off_sec, zone)
    @staticmethod
    def zero():
