    out=[]
    for ch in s:
        if ch in _SPECIAL_SLUG:
            out.append(_SPECIAL_SLUG[ch])
        elif ch in _GREEK:
            out.append(_GREEK[ch])
        elif ch in _CYRILLIC:
            out.append(_CYRILLIC[ch])
        else:
            out.append(ch)
    s=''.join(out)
    s=unicodedata.normalize('NFKD', s)
    s=''.join(ch for ch in s if not unicodedata.combining(ch))
    s=s.encode('ascii','ignore').decode('ascii')
    s=s.lower()
    # apostrophes removed in gosimple slug (l'hôtel -> lhotel): remove ' before token processing
    s=s.replace("'","")
    # Replace any sequence of characters not alnum/underscore/dash with dash
    s=re.sub(r'[^a-z0-9_-]+','-',s)
    s=re.sub(r'-+','-',s).strip('-')
    # gosimple: also strip leading/trailing underscores? Keep? It trims '-' only generally
    return s

def go_value_string(v):
    if v is None:
        return ''
    if isinstance(v, TimeValue):
        return v.go_string()
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, (list,tuple)):
        # Go fmt for slices in templates when rendered directly: earlier tags rendered as concatenated? Context values when used as variable {{tags}} output 'onetwo...' because slice rendering in raymond iterates? Actually raymond renders slice by concatenating elements.
        return ''.join(go_value_string(x) for x in v)
    if isinstance(v, dict):
        # Go map fmt: map[k:v k2:v2] sorted keys
        if not v:
            return 'map[]'
        parts=[]
        for k in sorted(v.keys(), key=lambda x: str(x)):
            val=v[k]
            if isinstance(val,(list,tuple)):
                vs='['+' '.join(go_value_string(x) for x in val)+']'
            else:
                vs=go_value_string(val)
            parts.append(f"{k}:{vs}")
        return 'map['+' '.join(parts)+']'
    return str(v)

def go_json_escape_str(s):
    # Go encoding/json with HTML escaping
    out='"'
    for ch in s:
        o=ord(ch)
        if ch=='"': out+='\\"'
        elif ch=='\\': out+='\\\\'
        elif ch=='\n': out+='\\n'
        elif ch=='\r': out+='\\r'
        elif ch=='\t': out+='\\t'
        elif ch=='<': out+='\\u003c'
        elif ch=='>': out+='\\u003e'
        elif ch=='&': out+='\\u0026'
        elif o<0x20:
            out+=f'\\u{o:04x}'
        elif o in (0x2028,0x2029):
            out+=f'\\u{o:04x}'
        else:
            out+=ch
    out+='"'
    return out

def go_json_dumps(obj):
    if obj is None:
        return 'null'
    if isinstance(obj, bool):
        return 'true' if obj else 'false'
    if isinstance(obj, TimeValue):
        return go_json_escape_str(obj.rfc3339nano())
    if isinstance(obj, (int,)):
        return str(obj)
    if isinstance(obj, float):
        # Go json floats: if integer valued, prints like 3? Python repr similar
        if obj==int(obj) and abs(obj)<1e15:
            return str(int(obj)) if False else repr(obj)  # Go prints 3.14, for 42.0 prints 42? json marshaling of interface float 42 -> 42
            # We'll handle below
        return repr(obj)
    if isinstance(obj, str):
        return go_json_escape_str(obj)
    if isinstance(obj, (list,tuple)):
        return '['+','.join(go_json_dumps(x) for x in obj)+']'
    if isinstance(obj, dict):
        # Go maps sorted keys; structs preserve field order if we use an ordered dict marked?
        # Our note/tag dicts are constructed with a special attribute for order via list subclass? We'll use key order as insertion for dicts that have '_ordered' flag stored separate globally?
        # Detect note-like dict by keys filename/title etc: use insertion order (Python dict retains)
        # For metadata maps, keys should be sorted: callers should pass sorted dict or we detect metadata by context.
        return '{'+','.join(go_json_escape_str(str(k))+':'+go_json_dumps(v) for k,v in obj.items())+'}'
    return go_json_escape_str(str(obj))

def go_json_dumps_float(f):
    return go_json_dumps(f)

# Fix float handling: override above for integral floats to match Go (42 -> 42)
_orig_go_json_dumps = go_json_dumps
def go_json_dumps(obj):  # noqa: F811
    if isinstance(obj, float):
        if obj.is_integer() and abs(obj) < 1e15:
            return str(int(obj))
        return repr(obj)
    return _orig_go_json_dumps(obj)

class Ctx(dict):
    # dict with normalized key lookup for template paths
    def lookup(self, name):
        if name in self:
            return self[name]
        norm=_norm_key(name)
        for k,v in self.items():
            if _norm_key(str(k))==norm:
                return v
        return None
    def has(self,name):
        if name in self: return True
        norm=_norm_key(name)
        return any(_norm_key(str(k))==norm for k in self.keys())

def _norm_key(name):
    return name.replace('-','').replace('_','').lower()

def ctx_wrap(v):
    if isinstance(v, dict) and not isinstance(v, Ctx):
        c=Ctx()
        for k,val in v.items():
            c[k]=ctx_wrap(val)
        return c
    if isinstance(v, list):
        return [ctx_wrap(x) for x in v]
    return v

def lookup_path(base, path_str):
    if path_str in ('this','.',''):
        return base
    # split by . but keep [n]
    parts=[]
    cur=''
    i=0
    # tokenise path: split on '.' outside brackets
    tokens=[]
    buf=''
    while i < len(path_str):
        ch=path_str[i]
        if ch=='.':
            if buf: tokens.append(buf); buf=''
            i+=1; continue
        elif ch=='[':
            if buf: tokens.append(buf); buf=''
            j=path_str.find(']',i)
            if j==-1:
                buf+=ch; i+=1; continue
            tokens.append(path_str[i:j+1]); i=j+1
            if i < len(path_str) and path_str[i]=='.': i+=1
            continue
        else:
            buf+=ch; i+=1
    if buf: tokens.append(buf)
    cur_obj=base
    for tok in tokens:
        if tok in ('this','.'):
            continue
        if tok.startswith('[') and tok.endswith(']'):
            inner=tok[1:-1].strip()
            if inner.startswith(('"',"'")):
                key=inner[1:-1]
                if isinstance(cur_obj, dict): cur_obj=cur_obj.lookup(key) if isinstance(cur_obj,Ctx) else cur_obj.get(key)
                else: return None
            else:
                try: idx=int(inner)
                except: return None
                if isinstance(cur_obj,(list,tuple)) and -len(cur_obj)<=idx<len(cur_obj): cur_obj=cur_obj[idx]
                else: return None
        else:
            if isinstance(cur_obj, Ctx):
                cur_obj=cur_obj.lookup(tok)
            elif isinstance(cur_obj, dict):
                if tok in cur_obj: cur_obj=cur_obj[tok]
                else:
                    # normalized fallback
                    norm=_norm_key(tok); found=None; ok=False
                    for k,v in cur_obj.items():
                        if _norm_key(str(k))==norm: found=v; ok=True; break
                    cur_obj=found if ok else None
            elif isinstance(cur_obj,(list,tuple)):
                return None
            else:
                return None
        if cur_obj is None:
            return None
    return cur_obj

# Token / AST
class Token:
    def __init__(self, kind, value, pos, raw=None):
        self.kind=kind; self.value=value; self.pos=pos; self.raw=raw if raw is not None else value
    def node_repr(self):
        if self.kind=='string':
            v=str(self.value).replace("'","\\'")
            return f"String{{Value:'{v}', Pos:{self.pos}}}"
        if self.kind=='number':
            return f"Number{{Value:{self.value}, Pos:{self.pos}}}"
        if self.kind=='path':
            return f"Path{{Original:'{self.value}', Pos:{self.pos}}}"
        if self.kind=='bool':
            return f"Bool{{Value:{str(self.value).lower()}, Pos:{self.pos}}}"
        return f"Path{{Original:'{self.value}', Pos:{self.pos}}}"

class NodeText:
    def __init__(self,text): self.text=text
class NodeExpr:
    def __init__(self, tokens, expr_pos, is_triple=False, is_block_open=False):
        self.tokens=tokens; self.expr_pos=expr_pos; self.is_triple=is_triple
class NodeBlock:
    def __init__(self, head_tokens, expr_pos):
        self.head_tokens=head_tokens; self.expr_pos=expr_pos; self.children=[]; self.else_children=None

def _find_expr_end(text, start):
    # start is index of '{{' ; find '}}' or '}}}' not in string
    i=start+2
    in_s=None; esc=False
    while i < len(text)-1:
        ch=text[i]
        if in_s:
            if esc: esc=False
            elif ch=='\\': esc=True
            elif ch==in_s: in_s=None
            i+=1; continue
        if ch in ('"',"'"):
            in_s=ch; i+=1; continue
        if text.startswith('}}}', i):
            return i,3
        if text.startswith('}}', i):
            return i,2
        i+=1
    return -1,0

def parse_template(text):
    nodes=[]
    stack=[]  # list of NodeBlock
    current_children=lambda: (stack[-1].else_children if (stack and stack[-1].else_children is not None) else (stack[-1].children if stack else nodes))
    def add_node(n):
        if stack:
            blk=stack[-1]
            if blk.else_children is not None: blk.else_children.append(n)
            else: blk.children.append(n)
        else:
            nodes.append(n)
    i=0
    while i < len(text):
        j=text.find('{{', i)
        if j==-1:
            add_node(NodeText(text[i:])); break
        if j>i:
            add_node(NodeText(text[i:j]))
        # escaped?
        if j>0 and text[j-1]=='\\':
            # remove handling in text node: we left backslash in previous text? Simpler: treat as literal {{ }}
            # Remove trailing backslash from last text node and add literal
            # find last text node etc. Skip complexity
            pass
        # comment?
        if text.startswith('{{!--', j):
            end=text.find('--}}', j)
            if end==-1: raise TemplateParseError("Unclosed expression")
            i=end+4; continue
        if text.startswith('{{!', j):
            end=text.find('}}', j)
            if end==-1: raise TemplateParseError("Unclosed expression")
            i=end+2; continue
        end,elen=_find_expr_end(text,j)
        if end==-1:
            # Determine lexer error
            inner=text[j+2:]
            # If there's a single } in inner as in {{title}
            # raymond reports Unexpected character ... '}'
            # If inner contains a '}' character not closing?
            if '}' in inner:
                # find position of stray }
                raise TemplateParseError("Parse error on line 1:\nLexer error\nToken: Error{\"Unexpected character in expression: '}'\"}")
            raise TemplateParseError("Parse error on line 1:\nLexer error\nToken: Error{\"Unclosed expression\"}")
        inner=text[j+2:end]
        is_triple=(elen==3)
        if is_triple:
            inner=inner  # first char maybe { ? _find returns for }}} inner excludes {{{? Actually start at j, {{{ - inner starts with '{'
            if inner.startswith('{'): inner=inner[1:]
        inner_strip=inner.strip()
        # empty expression?
        tokens=_tokenize_expr(inner, j+2, text)
        if inner_strip.startswith('#'):
            # block open: tokenize after #
            # tokens first token includes #? our tokenizer will treat # as part? handle
            blk_tokens=_tokenize_expr(inner_strip[1:].lstrip(), j+2+ (inner.find(inner_strip)+1), text)
            blk=NodeBlock(blk_tokens, j)
            add_node(blk); stack.append(blk)
        elif inner_strip.startswith('/'):
            name=inner_strip[1:].strip().split()[0] if inner_strip[1:].strip() else ''
            if not stack:
                raise TemplateParseError("Parse error on line 1:\nLexer error\nToken: Error{\"Unclosed expression\"}")
            stack.pop()
        elif inner_strip=='else' or inner_strip=='^':
            if stack:
                stack[-1].else_children=[]
            else:
                add_node(NodeText(''))
        elif inner_strip.startswith('^'):
            # inverse block
            blk_tokens=_tokenize_expr(inner_strip[1:].lstrip(), j+2, text)
            blk=NodeBlock(blk_tokens, j)
            # mark inverse by special head token?
            blk.inverse=True
            add_node(blk); stack.append(blk)
        else:
            add_node(NodeExpr(tokens, j, is_triple))
        i=end+elen
    if stack:
        # unclosed block - raymond may error? Treat as parse error
        raise TemplateParseError("Parse error on line 1:\nLexer error\nToken: Error{\"Unclosed expression\"}")
    return nodes

def _tokenize_expr(inner, base_offset, whole):
    # inner is raw inside {{ }}, base_offset is index in whole where inner starts (j+2)
    tokens=[]
    i=0
    # inner may include leading spaces; token pos should be absolute in whole
    while i < len(inner):
        while i < len(inner) and inner[i] in ' \t\r\n': i+=1
        if i>=len(inner): break
        start=i
        abs_pos=base_offset+start
        ch=inner[i]
        if ch=='(':
            tokens.append(Token('lparen','(',abs_pos)); i+=1; continue
        if ch==')':
            tokens.append(Token('rparen',')',abs_pos)); i+=1; continue
        if ch in ('"',"'"):
            quote=ch; i+=1; buf=""
            while i < len(inner) and inner[i]!=quote:
                if inner[i]=='\\' and i+1<len(inner):
                    nxt=inner[i+1]
                    mp={'n':'\n','t':'\t','r':'\r','"':'"','\\':'\\','/':'/',"'":"'",'b':'\b','f':'\f'}
                    if nxt in mp: buf+=mp[nxt]
                    else: buf+=nxt
                    i+=2
                else:
                    buf+=inner[i]; i+=1
            i+=1 # closing
            tokens.append(Token('string',buf,abs_pos))
            continue
        # read until space or ) ( 
        j=i
        while j < len(inner) and inner[j] not in ' \t\r\n()': j+=1
        word=inner[i:j]
        # number?
        if re.match(r'^-?\d+$', word):
            try: tokens.append(Token('number',int(word),abs_pos)); i=j; continue
            except: pass
        if re.match(r'^-?\d+\.\d+$', word):
            try: tokens.append(Token('number',float(word),abs_pos)); i=j; continue
            except: pass
        if word in ('true','false'):
            tokens.append(Token('bool', word=='true', abs_pos)); i=j; continue
        # path (may contain = for hash args like key=value; raymond splits? Keep as is parser later)
        tokens.append(Token('path',word,abs_pos))
        i=j
    return tokens

class RenderEnv:
    def __init__(self, warn_func=None, fatal_func=None, slug_language='en', now_ref=None, note_json_func=None, style_enabled=False):
        self.warn=warn_func or (lambda msg: sys.stderr.write(msg if msg.endswith('\n') else msg+'\n'))
        self.slug_language=slug_language
        self.now_ref=now_ref  # TimeValue for relative dates
        self.note_json_func=note_json_func
        self.style_enabled=style_enabled

def _is_truthy(v):
    if v is None: return False
    if isinstance(v,bool): return v
    if isinstance(v,(int,float)): return v!=0
    if isinstance(v,str): return len(v)>0
    if isinstance(v,(list,tuple,dict)): return len(v)>0
    return True

def _eval_token(tok, scopes, env):
    if tok.kind=='string': return tok.value
    if tok.kind=='number': return tok.value
    if tok.kind=='bool': return tok.value
    if tok.kind=='path':
        # handle @index etc
        name=tok.value
        if name.startswith('@'):
            # look in scopes metadata (stored as special dict in scope list as tuple)
            for scope, meta in reversed(scopes):
                if meta and name in meta: return meta[name]
            return None
        if name.startswith('../'):
            # parent scope
            depth=name.count('../')
            base_name=name.replace('../','')
            idx=max(0,len(scopes)-1-depth)
            base=scopes[idx][0]
            if base_name in ('','this','.'): return base
            return lookup_path(base, base_name)
        return lookup_path(scopes[-1][0], name)
    return None

def _eval_expr_tokens(tokens, scopes, env, expr_pos):
    # returns value; may raise TemplateEvalError/TemplateFatal
    if not tokens:
        return ''
    # subexpressions parentheses handling: simplify by evaluating groups first via recursion stack
    # Convert tokens with parens to evaluated values list of (token_or_value)
    # We'll parse into a list of items: each item is Token or ('sub', tokens)
    items=[]
    i=0
    while i < len(tokens):
        if tokens[i].kind=='lparen':
            depth=1; j=i+1; sub=[]
            while j < len(tokens) and depth>0:
                if tokens[j].kind=='lparen': depth+=1
                elif tokens[j].kind=='rparen':
                    depth-=1
                    if depth==0: break
                sub.append(tokens[j]); j+=1
            val=_eval_expr_tokens(sub, scopes, env, expr_pos)
            items.append(('value',val, tokens[i]))
            i=j+1
        else:
            items.append(('token',tokens[i],tokens[i])); i+=1
    # hash args key=value tokens: path tokens containing '='
    # Expand: token path 'key=value' or separate? handle later ignoring
    if len(items)==1:
        kind, val_tok, tok = items[0]
        if kind=='value': return val_tok
        tok=val_tok
        if tok.kind!='path':
            return tok.value
        name=tok.value
        # single identifier that is a strict helper requiring args
        if name in ('format-date','date'):
            raise TemplateEvalError(f"Helper '{name}' called with wrong number of arguments, needed 2 but got 0", expr_node=tok, expr_pos=expr_pos, helper_name=name)
        # variable lookup
        return _eval_token(tok, scopes, env)
    # helper call: first item must be path token
    first_kind, first_val, first_tok = items[0]
    if first_kind!='token' or first_val.kind!='path':
        return ''
    helper_name=first_val.value
    arg_items=items[1:]
    # Separate positional and hash arguments (tokens with '=' in path and next token as value? raymond: key=value where value attached or next?)
    args=[]; arg_tokens=[]
    hash_args={}
    idx=0
    while idx < len(arg_items):
        kind,val,tok = arg_items[idx]
        if kind=='token' and val.kind=='path' and '=' in val.value:
            key,eqval=val.value.split('=',1)
            if eqval=='':
                # value is next item
                if idx+1 < len(arg_items):
                    nk,nv,ntok=arg_items[idx+1]
                    hash_args[key]= nv if nk=='value' else _eval_token(nv, scopes, env)
                    idx+=2; continue
                else:
                    hash_args[key]=''; idx+=1; continue
            else:
                # eqval could be a literal path name to evaluate? treat as variable if not quoted (it was part of token, raymond treats as path)
                # try lookup; if not found use raw string
                v=lookup_path(scopes[-1][0], eqval)
                hash_args[key]=v if v is not None else eqval
                idx+=1; continue
        args.append(val if kind=='value' else _eval_token(val, scopes, env))
        arg_tokens.append(tok)
        idx+=1
    return _call_helper(helper_name, args, arg_tokens, scopes, env, expr_pos, tokens)

def _helper_type_name(v):
    if isinstance(v,str): return 'string'
    if isinstance(v,bool): return 'bool'
    if isinstance(v,int): return 'int'
    if isinstance(v,float): return 'float64'
    if isinstance(v, TimeValue): return 'time.Time'
    if isinstance(v,list): return '[]string'
    if isinstance(v,dict): return 'map[string]interface {}'
    if v is None: return '<nil>'
    return type(v).__name__

def _raise_wrong_args(helper, needed, got, arg_tokens, expr_pos, first_tok=None):
    if arg_tokens:
        node=arg_tokens[-1]
        # arg_tokens elements could be Token
        if isinstance(node, Token):
            node_repr=node.node_repr()
        else:
            node_repr=str(node)
    else:
        # Expr node
        if first_tok is not None:
            node_repr=f"Expr{{Path:Path{{Original:'{helper}', Pos:{first_tok.pos}}}, Pos:{expr_pos}}}"
        else:
            node_repr=f"Expr{{Path:Path{{Original:'{helper}', Pos:{expr_pos+2}}}, Pos:{expr_pos}}}"
    raise TemplateEvalError(f"Helper '{helper}' called with wrong number of arguments, needed {needed} but got {got}", current_node=node_repr)

def _raise_type_error(helper, arg_index, val, expected, arg_tokens):
    if arg_tokens:
        node=arg_tokens[-1]
        node_repr=node.node_repr() if isinstance(node,Token) else str(node)
    else:
        node_repr=''
    raise TemplateEvalError(f"Helper {helper} called with argument {arg_index} with type {_helper_type_name(val)} but it should be {expected}", current_node=node_repr)

def _call_helper(name, args, arg_tokens, scopes, env, expr_pos, all_tokens):
    first_tok=all_tokens[0] if all_tokens else None
    # Unknown helpers silently return ''
    known=('format-date','date','slug','join','concat','prepend','style','json')
    if name not in known:
        return ''
    if name=='slug':
        if len(args)!=1:
            _raise_wrong_args(name,1,len(args),arg_tokens,expr_pos,first_tok)
        return slugify(go_value_string(args[0]), language=env.slug_language)
    if name=='concat':
        if len(args)!=2:
            _raise_wrong_args(name,2,len(args),arg_tokens,expr_pos,first_tok)
        return go_value_string(args[0])+go_value_string(args[1])
    if name=='prepend':
        if len(args)==1:
            return ''
        if len(args)!=2:
            _raise_wrong_args(name,2,len(args),arg_tokens,expr_pos,first_tok)
        return go_value_string(args[0])+go_value_string(args[1])
    if name=='style':
        if len(args)==1:
            return ''
        if len(args)!=2:
            _raise_wrong_args(name,2,len(args),arg_tokens,expr_pos,first_tok)
        style_str=go_value_string(args[0]); text=go_value_string(args[1])
        return apply_style(style_str, text, env)
    if name=='join':
        if len(args)!=2:
            _raise_wrong_args(name,2,len(args),arg_tokens,expr_pos,first_tok)
        if not isinstance(args[0], (list,tuple)):
            _raise_type_error(name,0,args[0],'[]string',arg_tokens)
        sep=go_value_string(args[1]) if isinstance(args[1],str) else ''
        # if sep not string original ignores? join tags 123 returned tags joined with ''? We set ''.
        return sep.join(go_value_string(x) for x in args[0])
    if name=='json':
        if len(args)>1:
            _raise_wrong_args(name,1,len(args),arg_tokens,expr_pos,first_tok)
        if len(args)==0:
            return '{}'
        v=args[0]
        if env.note_json_func:
            # if v is a note/tag dict, custom serializer passed may handle; else generic
            try:
                return env.note_json_func(v)
            except Exception:
                pass
        return go_json_dumps(v)
    if name=='format-date':
        if len(args)==0:
            _raise_wrong_args(name,2,0,arg_tokens,expr_pos,first_tok)
        if len(args)>2:
            _raise_wrong_args(name,2,len(args),arg_tokens,expr_pos,first_tok)
        v=args[0]
        if v is None:
            return ''
        if not isinstance(v, TimeValue):
            _raise_type_error(name,0,v,'time.Time',arg_tokens)
        fmt='%Y-%m-%d'
        if len(args)==2 and isinstance(args[1],str):
            fmt=args[1]
        # if fmt empty? test returns? treat as default? Original strftime empty returns ''
        if fmt=='':
            return ''
        return format_date_strftime(v, fmt, env)
    if name=='date':
        if len(args)==0:
            _raise_wrong_args(name,2,0,arg_tokens,expr_pos,first_tok)
        # too many? If >? date helper expects 1 human arg but tolerates 2 (second ignored). If >2 error maybe?
        if len(args)>2:
            _raise_wrong_args(name,2,len(args),arg_tokens,expr_pos,first_tok)
        v=args[0]
        if isinstance(v, TimeValue):
            raise TemplateFatal("the {{date}} template helper was renamed to {{format-date}}, please update your configuration")
        if not isinstance(v,str):
            env.warn("zk: the {{date}} template helper expects a natural human date as a string for its only argument")
            return TimeValue.zero()
        # parse human date: will be handled by env-provided parser? Use internal import lazily to avoid circular
        try:
