_STYLE_ATTRS={'bold':1,'faint':2,'italic':3,'underline':4,'blink':5,'reverse':7,'hidden':8,'strikethrough':9}
_STYLE_COLORS={'black':30,'red':31,'green':32,'yellow':33,'blue':34,'magenta':35,'cyan':36,'white':37,
