def apply_style(style_str, text, env):
    if text=='':
        # style helper on empty still may validate
        pass
    rules=style_str.split() if style_str else []
    seqs=[]
    has_attr=False; has_color=False; has_bg=False
    for r in rules:
        if r in _STYLE_ATTRS:
            seqs.append(f"\x1b[{_STYLE_ATTRS[r]}m"); has_attr=True
        elif r in _STYLE_COLORS:
            seqs.append(f"\x1b[{_STYLE_COLORS[r]}m"); has_color=True
        elif r.endswith('-bg'):
            base=r[:-3]
            if base in _STYLE_COLORS:
                seqs.append(f"\x1b[{_STYLE_COLORS[base]+10}m"); has_bg=True
            else:
                env.warn(f"zk: warning: unknown styling rule: {r}")
        else:
            env.warn(f"zk: warning: unknown styling rule: {r}")
    if not env.style_enabled or not seqs:
        return text
    # termenv-like: prefix sequences combined? Our separate sequences are equivalent visually but raw for predefined formats need combined?
    # Predefined templates produce sequences as separate ESC[1m ESC[33m etc when captured via pane; raw pipe via pager had combined 1;33.
    # Termenv actually outputs \x1b[1;33m when writing directly? Captured pane converts.
    # We'll emit each sequence separately to match pane capture segments: \x1b[1m\x1b[33m text \x1b[0m\x1b[39m\x1b[49m
    prefix=''.join(seqs)
    # reset logic based on original: if any attribute, reset includes 0m 39m 49m; if only color, only 39m (fg) or 49m (bg)
    if has_attr:
        suffix="\x1b[0m\x1b[39m\x1b[49m"
    elif has_color and has_bg:
        suffix="\x1b[39m\x1b[49m"
    elif has_color:
        suffix="\x1b[39m"
    elif has_bg:
        suffix="\x1b[49m"
    else:
        suffix="\x1b[0m"
    return prefix+text+suffix

def format_date_strftime(tv, fmt, env):
    # Lazy import formatter from main? Implement here
    try:
        return _strftime(tv, fmt)
    except _StrftimeError as e:
        env.warn(f"zk: the {{{{format-date}}}} template helper failed to format the date: {e}")
        return ''

class _StrftimeError(Exception): pass

def _strftime(tv, fmt):
    wall=tv.wall_datetime()
    # For zero time, wall is year1
    out=""
    i=0
    # pre-check stray
    while i < len(fmt):
        ch=fmt[i]
        if ch!='%':
            out+=ch; i+=1; continue
        if i+1>=len(fmt):
            raise _StrftimeError("failed to compile format: stray % at the end of pattern")
        code=fmt[i+1]
        # specifications set from lestrrat strftime: support many
        spec={
            '%':'%', 'Y':lambda: f"{wall.year:04d}", 'y':lambda: f"{wall.year%100:02d}", 'm':lambda: f"{wall.month:02d}", 'd':lambda: f"{wall.day:02d}", 'e':lambda: f"{wall.day:2d}",
            'H':lambda: f"{wall.hour:02d}", 'I':lambda: f"{((wall.hour-1)%12)+1:02d}", 'M':lambda: f"{wall.minute:02d}", 'S':lambda: f"{wall.second:02d}",
            'p':lambda: "AM" if wall.hour<12 else "PM", 'P':lambda: "am" if wall.hour<12 else "pm",
            'b':lambda: wall.strftime("%b"), 'B':lambda: wall.strftime("%B"), 'h':lambda: wall.strftime("%b"),
            'a':lambda: wall.strftime("%a"), 'A':lambda: wall.strftime("%A"),
            'j':lambda: f"{wall.timetuple().tm_yday:03d}",
            'U':lambda: f"{int(wall.strftime('%U')):02d}", 'W':lambda: f"{int(wall.strftime('%W')):02d}",
            'w':lambda: str((wall.weekday()+1)%7), 'u':lambda: str(wall.isoweekday()),
            'z':lambda: _tz_offset_str(tv, colon=False), 'Z':lambda: _tz_name(tv),
            's':lambda: str(tv.epoch_ns//1_000_000_000 if not tv.is_zero() else -62135596800),
            'R':lambda: f"{wall.hour:02d}:{wall.minute:02d}", 'T':lambda: f"{wall.hour:02d}:{wall.minute:02d}:{wall.second:02d}",
            'r':lambda: f"{((wall.hour-1)%12)+1:02d}:{wall.minute:02d}:{wall.second:02d} {'AM' if wall.hour<12 else 'PM'}",
            'D':lambda: f"{wall.month:02d}/{wall.day:02d}/{wall.year%100:02d}", 'F':lambda: f"{wall.year:04d}-{wall.month:02d}-{wall.day:02d}",
            'k':lambda: f"{wall.hour:2d}", 'l':lambda: f"{((wall.hour-1)%12)+1:2d}",
            'c':lambda: wall.strftime("%a %b %e %H:%M:%S %Y"), 'x':lambda: f"{wall.month:02d}/{wall.day:02d}/{wall.year:04d}", 'X':lambda: f"{wall.hour:02d}:{wall.minute:02d}:{wall.second:02d}",
            'n':lambda: "\n", 't':lambda: "\t", 'C':lambda: f"{wall.year//100:02d}", 'g':lambda: f"{wall.isocalendar()[0]%100:02d}", 'G':lambda: f"{wall.isocalendar()[0]:04d}", 'V':lambda: f"{wall.isocalendar()[1]:02d}",
        }
        if code not in spec:
            raise _StrftimeError(f"failed to compile format: pattern compilation failed: lookup failed: '%{code}' was not found in specification set")
        out+=spec[code]()
        i+=2
    return out

def _tz_offset_str(tv, colon=False):
    off=tv.offset_sec; sign="+" if off>=0 else "-"; ao=abs(off)
    return f"{sign}{ao//3600:02d}{':' if colon else ''}{(ao%3600)//60:02d}"
def _tz_name(tv):
    z=tv.zone_name
    if tv.offset_sec==0: return "UTC"
    if re.match(r'^[+-]\d{2}:\d{2}$', z): return f"{z[:3]}{z[4:]}"
    return z

def render_template(template_text, context, env=None):
    if env is None: env=RenderEnv()
    try:
        nodes=parse_template(template_text)
    except TemplateParseError as e:
        raise
    scopes=[(ctx_wrap(context), None)]
    out=[]
    _render_nodes(nodes, scopes, env, out)
    return ''.join(out)

def _render_nodes(nodes, scopes, env, out):
    for node in nodes:
        if isinstance(node, NodeText):
            out.append(node.text)
        elif isinstance(node, NodeExpr):
            val=_eval_expr_tokens(node.tokens, scopes, env, node.expr_pos)
            out.append(go_value_string(val))
        elif isinstance(node, NodeBlock):
            _render_block(node, scopes, env, out)

def _render_block(node, scopes, env, out):
    if not node.head_tokens:
        return
    head_name=node.head_tokens[0].value if node.head_tokens[0].kind=='path' else ''
    is_inverse=getattr(node,'inverse',False)
    # Built-in blocks
    if head_name=='if' or head_name=='unless':
        # evaluate argument expr (tokens after name as expression)
        arg_tokens=node.head_tokens[1:]
        val=_eval_expr_tokens(arg_tokens, scopes, env, node.expr_pos) if arg_tokens else None
        truth=_is_truthy(val)
        if head_name=='unless': truth=not truth
        if is_inverse: truth=not truth
        if truth:
            _render_nodes(node.children, scopes, env, out)
        elif node.else_children is not None:
            _render_nodes(node.else_children, scopes, env, out)
        return
    if head_name=='each':
        arg_tokens=node.head_tokens[1:]
        val=_eval_expr_tokens(arg_tokens, scopes, env, node.expr_pos) if arg_tokens else None
        if isinstance(val,(list,tuple)) and len(val)>0:
            for idx,item in enumerate(val):
                meta={'@index':idx,'@first':idx==0,'@last':idx==len(val)-1,'@key':idx}
                scopes.append((ctx_wrap(item), meta))
                _render_nodes(node.children, scopes, env, out)
                scopes.pop()
        elif isinstance(val,dict) and len(val)>0:
            items=list(val.items())
            for idx,(k,item) in enumerate(items):
                meta={'@index':idx,'@first':idx==0,'@last':idx==len(items)-1,'@key':k}
                scopes.append((ctx_wrap(item), meta))
                _render_nodes(node.children, scopes, env, out)
                scopes.pop()
        elif node.else_children is not None:
            _render_nodes(node.else_children, scopes, env, out)
        return
    if head_name=='with':
        arg_tokens=node.head_tokens[1:]
        val=_eval_expr_tokens(arg_tokens, scopes, env, node.expr_pos) if arg_tokens else None
        if _is_truthy(val):
            scopes.append((ctx_wrap(val), None))
            _render_nodes(node.children, scopes, env, out)
            scopes.pop()
        elif node.else_children is not None:
            _render_nodes(node.else_children, scopes, env, out)
        return
    # Generic block over a path/helper
    val=_eval_expr_tokens(node.head_tokens, scopes, env, node.expr_pos)
    if is_inverse:
        if not _is_truthy(val):
            _render_nodes(node.children, scopes, env, out)
        elif node.else_children is not None:
            _render_nodes(node.else_children, scopes, env, out)
        return
    if isinstance(val,(list,tuple)):
        if len(val)==0:
            if node.else_children is not None: _render_nodes(node.else_children, scopes, env, out)
            return
        for idx,item in enumerate(val):
            meta={'@index':idx,'@first':idx==0,'@last':idx==len(val)-1,'@key':idx}
            scopes.append((ctx_wrap(item), meta))
            _render_nodes(node.children, scopes, env, out)
            scopes.pop()
        return
    if isinstance(val,dict) and val:
        scopes.append((ctx_wrap(val), None))
        _render_nodes(node.children, scopes, env, out)
        scopes.pop(); return
    if _is_truthy(val):
        # If val is scalar, this context remains? raymond sets context to val for primitives? For string, {{#title}} {{.}} would be title
        if isinstance(val,(str,int,float,bool)):
            scopes.append((val, None))
            _render_nodes(node.children, scopes, env, out)
            scopes.pop()
        else:
            _render_nodes(node.children, scopes, env, out)
    elif node.else_children is not None:
        _render_nodes(node.else_children, scopes, env, out)
