    s=re.sub(r'\\([\\`*{}\[\]()#+\-.!_>])', r'\1', s)
    # restore code
    def restore(m): return placeholders[int(m.group(1))]
    s=re.sub(r'\x00(\d+)\x00', restore, s)
    return s.strip()

def parse_note_text(raw_text, existing_created=None, config=None):
    # config dict with flags hashtags/colon/multiword
    if config is None: config={}
    hashtags=config.get('hashtags', True)
    colon_tags=config.get('colon_tags', False)
    multiword_tags=config.get('multiword_tags', False)
    p=ParsedNote()
    p.raw_content=raw_text
    p.checksum=hashlib.sha256(raw_text.encode('utf-8', errors='surrogatepass')).hexdigest()
    p.word_count=len(re.findall(r'\S+', raw_text, flags=re.UNICODE))
    fm=detect_frontmatter(raw_text)
    metadata={}
    fm_end=0
    fm_title=None
    if fm:
        yaml_text, fm_end, _ = fm
        try:
            y=parse_yaml(yaml_text)
            if isinstance(y,dict):
                metadata=_lower_keys(y)
        except Exception:
            metadata={}
    p.metadata=metadata
    # title from frontmatter if present and not None
    if 'title' in metadata and metadata['title'] is not None:
        fm_title=stringify_yaml_value(metadata['title'])
    # heading search after fm_end
    rest_text=raw_text[fm_end:] if fm else raw_text
    rest_offset=fm_end if fm else 0
    heading_info=None  # (title, body_start_abs, heading_block_abs_start, heading_block_abs_end)
    if fm_title is None:
        heading_info=_find_first_heading(raw_text, rest_offset)
    if fm_title is not None:
        p.title=fm_title
        body_start=fm_end if fm else 0
    elif heading_info:
        p.title=heading_info[0]
        body_start=heading_info[1]
    else:
        p.title=''
        body_start=0
    body=raw_text[body_start:] if body_start<=len(raw_text) else ''
    p.body=body.strip(' \t\r\n')
    # lead: first block (split by blank lines)
    if p.body:
        # split on blank line pattern
        m=re.search(r'\n[ \t]*\n', p.body)
        # More accurately split on \r?\n\s*\n - use regex on \n\n with possible \r and spaces
        blocks=re.split(r'\r?\n[ \t]*\r?\n|\n[ \t]*\n', p.body)
        # fallback above: use first chunk by pattern \n[ \t\r]*\n
        p.lead=_first_block(p.body)
    else:
        p.lead=''
    # Created
    if existing_created is not None:
        p.created=existing_created
    else:
        created=None
        if 'date' in metadata:
            created=parse_frontmatter_date(metadata['date'])
        p.created=created if created is not None else TimeValue.now()
    p.tags=_extract_tags(metadata, raw_text, fm_end if fm else 0, hashtags, colon_tags, multiword_tags)
    p.links=_extract_links(raw_text, fm_end if fm else 0, hashtags=hashtags)
    return p

def _first_block(body):
    # split by blank lines (a line containing only whitespace)
    lines=body.splitlines()
    block=[]
    for line in lines:
        if line.strip()=='':
            break
        block.append(line)
    return '\n'.join(block)

def _find_first_heading(text, start_offset):
    lines=_split_lines_keep(text)
    # compute line offsets; start at line containing start_offset
    # iterate lines with index
    in_fence=False; fence_char=None; fence_len=0
    paragraph_candidate=None  # (text, offset_of_first_line, end_of_first_line)
    prev_line=None
    for idx,(line,off,end) in enumerate(lines):
        if off < start_offset and end <= start_offset:
            prev_line=(line,off,end); continue
        # adjust first partial line if start_offset inside?
        content=_line_content(line)
        stripped=content.strip()
        # fence tracking
        fence_match=re.match(r'^ {0,3}(`{3,}|~{3,})', content)
        if fence_match:
            fc=fence_match.group(1)[0]; fl=len(fence_match.group(1))
            if not in_fence:
                in_fence=True; fence_char=fc; fence_len=fl
            elif fc==fence_char and fl>=fence_len:
                in_fence=False
            prev_line=(line,off,end); continue
        if in_fence:
            prev_line=(line,off,end); continue
        # ATX heading
        m=re.match(r'^ {0,3}(#{1,6})[ \t]+(.*)$', content)
        if m:
            heading_text=m.group(2).strip()
            # Remove closing sequence of hashes preceded by space
            heading_text=re.sub(r'[ \t]+#+[ \t]*$', '', heading_text)
            title=_inline_plain(heading_text)
            return (title, end, off, end)
        if m:=re.match(r'^ {0,3}(#{1,6})[ \t]*$', content):
            return ('', end, off, end)
        # Setext: previous line was a text candidate and this line is === or ---
        if prev_line is not None and re.match(r'^ {0,3}(=+|-+)[ \t]*$', content):
            prev_content=_line_content(prev_line[0])
            # prev must not be blank / not a heading / not list etc. Approx: if prev non-empty and not starting with > or - list? Goldmark setext applies to paragraph.
            if prev_content.strip() and not re.match(r'^ {0,3}(#{1,6})[ \t]', prev_content):
                # But if prev was a thematic break candidate? Exclude lines that are pure decorations
                title=_inline_plain(prev_content.strip())
                # body starts after prev line (includes underline line)
                return (title, prev_line[2], prev_line[1], end)
        prev_line=(line,off,end)
    return None

# ---- links ----

def _mask_code(text):
    # Return text with fenced code and inline code replaced by spaces (preserve length/offsets)
    chars=list(text)
    lines=_split_lines_keep(text)
    in_fence=False; fence_char=None; fence_len=0
    for line,off,end in lines:
        content=_line_content(line)
        fence_match=re.match(r'^ {0,3}(`{3,}|~{3,})', content)
        if fence_match:
            fc=fence_match.group(1)[0]; fl=len(fence_match.group(1))
            if not in_fence:
                in_fence=True; fence_char=fc; fence_len=fl
                for k in range(off,end): chars[k]=' ' if chars[k] not in '\r\n' else chars[k]
                continue
            elif fc==fence_char and fl>=fence_len:
                in_fence=False
                for k in range(off,end): chars[k]=' ' if chars[k] not in '\r\n' else chars[k]
                continue
        if in_fence:
            for k in range(off,end): chars[k]=' ' if chars[k] not in '\r\n' else chars[k]
    masked=''.join(chars)
    # inline code spans: replace content including backticks with spaces
    def repl(m):
        s=m.group(0)
        return ''.join(' ' if c not in '\r\n' else c for c in s)
    masked=re.sub(r'(`+)(.+?)\1', repl, masked, flags=re.S)
    return masked

def _blocks_after_fm(text, fm_end):
    # returns list of (snippet_text, start_offset, end_offset) for blocks split by blank lines
    segment=text[fm_end:]
    base=fm_end
    blocks=[]
    # split preserving offsets: iterate lines
    lines=_split_lines_keep(text)
    cur=[]
    cur_start=None
    def flush():
        nonlocal cur, cur_start
        if cur:
            block_text=''.join(l[0] for l in cur)
            # trim trailing newlines for snippet; snippet is trimmed block
            stripped=block_text.strip('\r\n')
            # strip trailing spaces? blocks in original snippets trimmed? Paragraph text not trailing spaces (except x13 hard break spaces preserved inside)
            stripped=stripped.strip()
            if stripped=='' and False:
                pass
            # start offset: for heading, offset after #; else offset of first non-whitespace
            first_line=_line_content(cur[0][0])
            m=re.match(r'^( {0,3}#{1,6}[ \t]+)', first_line)
            if m:
                start=cur[0][1]+len(m.group(1))
                # snippet text excludes # prefix for first line, but keeps rest lines as-is
                # rebuild snippet: first line without prefix + rest
                snippet_text=first_line[len(m.group(1)):].rstrip()
                if len(cur)>1:
                    rest=''.join(l[0] for l in cur[1:])
                    snippet_text=snippet_text+ '\n'+rest.strip('\r\n')
                    # Preserve internal as original: simpler use block stripped and remove prefix
                else:
                    snippet_text=first_line[len(m.group(1)):].strip()
                end=start+len(snippet_text)
                # Actually snippet end in raw: start+len(snippet) if single line matches; multi-line approximate
                blocks.append((snippet_text, start, start+len(snippet_text)))
            else:
                # find first non whitespace in block
                bt=''.join(l[0] for l in cur)
                lead_len=len(bt)-len(bt.lstrip(' \t\r\n'))
                start=cur[0][1]+lead_len
                snippet_text=bt.strip()
                blocks.append((snippet_text, start, start+len(snippet_text)))
            cur=[]; cur_start=None
    for line,off,end in lines:
        if off < fm_end:
            continue
        content=_line_content(line)
        if content.strip()=='':
            flush()
        else:
            cur.append((line,off,end))
    flush()
    return blocks

def _snippet_for_offset(blocks, offset, text):
    for snippet,start,end in blocks:
        if start <= offset < end or (start <= offset and offset <= end+2000 and snippet in text[offset-200:offset+2000]):
            return snippet,start,end
    # find block containing offset by raw block ranges: fallback use block whose start<=offset and next start>offset
    cand=None
    for snippet,start,end in blocks:
        if start<=offset:
            cand=(snippet,start,end)
        else:
            break
    if cand: return cand
    if blocks: return blocks[0]
    return ('',0,0)

def _extract_links(raw_text, fm_end, hashtags=True):
    masked=_mask_code(raw_text[fm_end:]) if fm_end else _mask_code(raw_text)
    full_masked = (' '*fm_end + masked) if fm_end else masked
    # reference definitions: lines like [label]: dest
    refs={}
    for m in re.finditer(r'(?m)^[ \t]{0,3}\[([^\]]+)\]:[ \t]*(\S+)', full_masked):
        label=m.group(1).strip().lower()
        dest=m.group(2).strip()
        if dest.startswith('<') and '>' in dest:
            dest=dest[1:dest.find('>')]
        refs[label]=dest
    blocks=_blocks_after_fm(raw_text, fm_end)
    links=[]
    # combined scanning
    # Pattern alternatives in order at each position: wiki, markdown inline, reference, shortcut
    i=fm_end
    text=full_masked
    while i < len(text):
        # wiki
        if text.startswith('[[', i):
            end=text.find(']]', i+2)
            if end!=-1:
                inside=text[i+2:end]
                # inside cannot contain newline? It can but ok; if contains '[' skip
                if '[' not in inside and ']' not in inside:
                    # split alias
                    if '|' in inside:
                        href,title=inside.split('|',1)
                        href=href.strip(); title=title.strip()
                    else:
                        href=inside.strip(); title=href
                    links.append(_make_link(title, href, 'wiki-link', i, text, blocks, raw_text))
                    i=end+2; continue
            i+=2; continue
        # markdown/image: check '!'?
        if text[i]=='!' and i+1 < len(text) and text[i+1]=='[':
            # skip image entirely
            end=_find_md_link_end(text,i+1)
            i=(end+1 if end!=-1 else i+2); continue
        if text[i]=='[':
            # footnote definition/reference skip
            if i+1 < len(text) and text[i+1]=='^':
                end=text.find(']', i)
                i=(end+1 if end!=-1 else i+1); continue
            # find closing bracket (handle nested somewhat)
            close=_find_closing_bracket(text,i)
            if close==-1:
                i+=1; continue
            title=text[i+1:close]
            # inline (...) 
            if close+1 < len(text) and text[close+1]=='(':
                end=_find_closing_paren(text, close+1)
                if end==-1:
                    i+=1; continue
                inside=text[close+2:end].strip()
                if inside=='':
                    i=end+1; continue
                # dest may be <...> or first token
                if inside.startswith('<'):
                    gt=inside.find('>')
                    dest=inside[1:gt] if gt!=-1 else inside
                else:
                    dest=inside.split()[0]
                links.append(_make_link(title, dest, 'markdown', i, text, blocks, raw_text, is_markdown_dest=True))
                i=end+1; continue
            elif close+1 < len(text) and text[close+1]=='[':
                close2=_find_closing_bracket(text, close+1)
                if close2==-1:
                    i+=1; continue
                label=text[close+2:close2]
                ref_key=(label or title).strip().lower()
                if ref_key in refs:
                    links.append(_make_link(title, refs[ref_key], 'markdown', i, text, blocks, raw_text, is_markdown_dest=True))
                i=close2+1; continue
            else:
                # shortcut reference [text]
                ref_key=title.strip().lower()
                if ref_key in refs:
                    links.append(_make_link(title, refs[ref_key], 'markdown', i, text, blocks, raw_text, is_markdown_dest=True))
                i=close+1; continue
        i+=1
    return links

def _find_closing_bracket(text, start):
    depth=0
    i=start
    while i < len(text):
        if text[i]=='\\': i+=2; continue
        if text[i]=='[': depth+=1
        elif text[i]==']':
            depth-=1
            if depth==0: return i
        i+=1
    return -1

def _find_closing_paren(text, start):
    depth=0; in_str=None
    i=start
    while i < len(text):
        ch=text[i]
        if in_str:
            if ch==in_str: in_str=None
            i+=1; continue
        if ch in ('"',"'"): in_str=ch
        elif ch=='(' : depth+=1
        elif ch==')':
            depth-=1
            if depth==0: return i
        i+=1
    return -1

def _find_md_link_end(text, start_bracket):
    close=_find_closing_bracket(text,start_bracket)
    if close==-1: return -1
    if close+1 < len(text) and text[close+1]=='(':
        return _find_closing_paren(text, close+1)
    if close+1 < len(text) and text[close+1]=='[':
        c2=_find_closing_bracket(text, close+1)
        return c2 if c2!=-1 else close
    return close

class LinkObj:
    pass

def _make_link(title, href, typ, offset, masked_text, blocks, raw_text, is_markdown_dest=False):
    l=LinkObj(); l.title=title; l.href_raw=href; l.type=typ; l.offset=offset; l.is_markdown_dest=is_markdown_dest
    snippet,start,end=_snippet_for_offset(blocks, offset, raw_text)
    l.snippet=snippet; l.snippet_start=start; l.snippet_end=end
    l.href=href  # will be normalized in DB layer for markdown
    # external determination on raw href
    l.is_external=False
    href_l=href.lower()
    if href_l.startswith('http://') or href_l.startswith('https://'):
        l.is_external=True
    return l

def _extract_tags(metadata, raw_text, fm_end, hashtags, colon_tags, multiword_tags):
    tags=[]
    seen=set()
    def add(t):
        if t is None: return
        ts=stringify_yaml_value(t) if not isinstance(t,str) else t
        # tags from fm: strings already, numbers become string; empty ignore?
        if ts=='' : return
        if ts not in seen:
            seen.add(ts); tags.append(ts)
    if 'tags' in metadata:
        mv=metadata['tags']
        if isinstance(mv,list):
            for item in mv: add(item)
        elif isinstance(mv,str):
            for tok in mv.split(): add(tok)
        elif mv is not None:
            add(mv)
    body_text=raw_text[fm_end:] if fm_end else raw_text
    masked=_mask_code(body_text)
    # mask wiki / markdown links for hashtag/colon scanning: replace link spans with spaces
    masked=_mask_links(masked)
    if hashtags:
        if multiword_tags:
            # find multiword terminated tags first? Approach scanning #
            i=0
            while i < len(masked):
                if masked[i]=='#' and _tag_boundary(masked,i):
                    # try find closing # on same line after at least one space-included phrase
                    rest=masked[i+1:]
                    # closing # search up to newline
                    nl=rest.find('\n'); limit=nl if nl!=-1 else len(rest)
                    closing=rest.find('#',0,limit if limit!=-1 else len(rest))
                    if closing!=-1 and ' ' in rest[:closing].strip() or (closing!=-1 and '\t' in rest[:closing]):
                        phrase=rest[:closing].strip()
                        # phrase must contain only word chars/spaces/-/_ etc and at least two words
                        if phrase and re.match(r'^[\w\-/ ]+$', phrase, flags=re.UNICODE):
                            add(phrase); i+=1+closing+1; continue
                    # fallback first word
                    m=re.match(r'([A-Za-z0-9_][A-Za-z0-9_/\-:]*)', rest)
                    # colon inclusion: original hashtag token may include trailing colon etc; our fallback below handles
                    tag=_scan_hashtag_token(rest)
                    if tag:
                        add(tag); i+=1+len(tag); continue
                i+=1
        else:
            i=0
            while i < len(masked):
                if masked[i]=='#' and _tag_boundary(masked,i):
                    tag=_scan_hashtag_token(masked[i+1:])
                    if tag:
                        add(tag); i+=1+len(tag); continue
                i+=1
    if colon_tags:
        # find colon sequences
        i=0
        # regex on masked
        for m in re.finditer(r'(?<![A-Za-z0-9_]):([A-Za-z0-9_][A-Za-z0-9_/\-]*(?::[A-Za-z0-9_][A-Za-z0-9_/\-]*)+):?', masked):
            # Need to verify pattern ended with : or the sequence match logic: our regex can match :one:two without trailing; special check:
            full=m.group(0)
            content=m.group(1)
            # If original text after content char is not ':' and content contains ':', then only first segment is a valid closed tag (as :one: case)
            # Determine indexes:
            start=m.start(); end=m.end()
            # If full doesn't end with ':' and ':' in content:
            if not full.endswith(':') and ':' in content:
                content=content.split(':')[0]
                add(content)
            else:
                for part in content.split(':'):
                    add(part)
    return tags

def _tag_boundary(text, i):
    if i==0: return True
    prev=text[i-1]
    # not preceded by alphanumeric / underscore (a#b invalid) - also not #?
    if prev.isalnum() or prev=='_' or prev=='#':
        return False
    return True

def _scan_hashtag_token(rest):
    if not rest: return None
    first=rest[0]
    # tag must start with allowed char: alphanumeric, underscore, '-' ? From examples #-dash captured, #under...; #" fails
    if not (first.isalnum() or first in '_-'):
        return None
    # consume chars alnum _ - / and colon (: allowed but maybe only if followed by alnum/space? t06 #tag: captured colon)
    i=0
    while i < len(rest) and (rest[i].isalnum() or rest[i] in '_-/:'):
        i+=1
    token=rest[:i]
    # trailing slash? keep? Probably trim trailing '/' ?
    # If token ends with colon and originally... keep as captured (t06)
    return token

def _mask_links(masked):
    chars=list(masked)
    # wiki
    for m in re.finditer(r'\[\[[^\]]*\]\]', masked):
        for k in range(m.start(), m.end()): chars[k]=' ' if chars[k] not in '\r\n' else chars[k]
    s=''.join(chars)
    # markdown links: replace entire [text](dest) or [text][ref]
    def repl(m):
        return ''.join(' ' if c not in '\r\n' else c for c in m.group(0))
    s=re.sub(r'!?\[[^\]]*\]\([^)]*\)', repl, s)
    s=re.sub(r'!?\[[^\]]*\]\[[^\]]*\]', repl, s)
    return s
