import re, hashlib, json
from yaml_min import parse_yaml
from timeutil import TimeValue, parse_frontmatter_date

def stringify_yaml_value(v):
    if v is None: return ''
    if isinstance(v,bool): return 'true' if v else 'false'
    if isinstance(v,(int,float)):
        # Go fmt: 42 -> 42, 3.14 -> 3.14
        if isinstance(v,float) and v.is_integer(): return str(int(v)) if False else str(v)
        return str(v)
    if isinstance(v,str): return v
    if isinstance(v,list): return '['+' '.join(stringify_yaml_value(x) for x in v)+']'
    if isinstance(v,dict): return 'map['+' '.join(f"{k}:{stringify_yaml_value(val)}" for k,val in sorted(v.items()))+']'
    return str(v)

def _lower_keys(obj):
    if isinstance(obj,dict):
        d={}
        for k,v in obj.items():
            d[str(k).lower()]=_lower_keys(v)
        return d
    if isinstance(obj,list):
        return [_lower_keys(x) for x in obj]
    return obj

class ParsedNote:
    pass

def _split_lines_keep(text):
    lines=[]
    i=0
    while i < len(text):
        j=text.find('\n', i)
        if j==-1:
            lines.append((text[i:], i, len(text))); break
        lines.append((text[i:j+1], i, j+1)); i=j+1
    if text=='':
        lines=[]
    return lines

def _line_content(line):
    return line.rstrip('\r\n')

def detect_frontmatter(text):
    lines=_split_lines_keep(text)
    if not lines: return None
    first=_line_content(lines[0][0])
    if not re.match(r'^-{2,}\s*$', first):
        return None
    for idx in range(1,len(lines)):
        content=_line_content(lines[idx][0])
        if re.match(r'^-{2,}\s*$', content):
            yaml_text=''.join(l[0] for l in lines[1:idx])
            end_offset=lines[idx][2]
            return (yaml_text, end_offset, idx)
    return None

def _inline_plain(s):
    # strip inline markdown to plain text for heading title
    # code spans first placeholders
    placeholders=[]
    def repl_code(m):
        placeholders.append(m.group(2) or '')
        return f"\x00{len(placeholders)-1}\x00"
    s=re.sub(r'(`+)(.+?)\1', repl_code, s, flags=re.S)
    # images/links
    s=re.sub(r'!\[([^\]]*)\]\([^)]*\)', r'\1', s)
    s=re.sub(r'!\[([^\]]*)\]\[[^\]]*\]', r'\1', s)
    s=re.sub(r'\[([^\]]+)\]\([^)]*\)', r'\1', s)
    s=re.sub(r'\[([^\]]+)\]\[[^\]]*\]', r'\1', s)
    # reference style shortcut?
    # HTML tags
    s=re.sub(r'<[^>]+>', '', s)
    # emphasis
    s=re.sub(r'(\*\*|__)(.+?)\1', r'\2', s)
    s=re.sub(r'(\*|_)(.+?)\1', r'\2', s)
    s=re.sub(r'~~(.+?)~~', r'\1', s)
    # footnote refs
    s=re.sub(r'\[\^[^\]]+\]', '', s)
    # backslash escapes
    s=re.sub(r'\\([\\`*{}\[\]()#+\-.!_>])', r'\1', s)
    # restore code
    def restore(m): return placeholders[int(m.group(1))]
    s=re.sub(r'\x00(\d+)\x00', restore, s)
    return s.strip()

def parse_note_text(raw_text, existing_created=None, config=None):
    # config dict with flags hashtags/colon/multiword
    if config is None: config={}
    hashtags=config.get('hashtags', True)
    colon_tags=config.get('colon_tags', False)
    multiword_tags=config.get('multiword_tags', False)
    p=ParsedNote()
    p.raw_content=raw_text
    p.checksum=hashlib.sha256(raw_text.encode('utf-8', errors='surrogatepass')).hexdigest()
    p.word_count=len(re.findall(r'\S+', raw_text, flags=re.UNICODE))
    fm=detect_frontmatter(raw_text)
    metadata={}
    fm_end=0
    fm_title=None
    if fm:
        yaml_text, fm_end, _ = fm
        try:
            y=parse_yaml(yaml_text)
            if isinstance(y,dict):
                metadata=_lower_keys(y)
        except Exception:
            metadata={}
