def _find_closing_bracket(text, start):
    depth=0
    i=start
    while i < len(text):
        if text[i]=='\\': i+=2; continue
        if text[i]=='[': depth+=1
        elif text[i]==']':
            depth-=1
            if depth==0: return i
        i+=1
    return -1

def _find_closing_paren(text, start):
    depth=0; in_str=None
    i=start
    while i < len(text):
        ch=text[i]
        if in_str:
            if ch==in_str: in_str=None
            i+=1; continue
        if ch in ('"',"'"): in_str=ch
        elif ch=='(' : depth+=1
        elif ch==')':
            depth-=1
            if depth==0: return i
        i+=1
    return -1

def _find_md_link_end(text, start_bracket):
    close=_find_closing_bracket(text,start_bracket)
