        raise TomlError(f"Can't convert {format_value_go(val)}({toml_type_name(val)}) to {expected_desc}", line, 1)
    def check(path, typ, desc):
        val,exists=get_path(path)
        if not exists: return
        if typ=='str' and not isinstance(val,str): err_for(path, desc, val)
        if typ=='int' and (not isinstance(val,int) or isinstance(val,bool)): err_for(path, desc, val)
        if typ=='bool' and not isinstance(val,bool): err_for(path, desc, val)
        if typ=='strlist':
            if not isinstance(val,list): err_for(path, desc, val)
            for el in val:
                if not isinstance(el,str): err_for(path, "string", el)
    # note
    for f in ['language','default-title','filename','extension','template','id-charset','id-case']:
        check(['note',f],'str','string')
    check(['note','id-length'],'int','int')
    check(['note','exclude'],'strlist','[]string(slice)')
    for f in ['link-format']:
        check(['format','markdown',f],'str','string')
    for f in ['link-encode-path','link-drop-extension','hashtags','colon-tags','multiword-tags']:
        check(['format','markdown',f],'bool','bool')
    for f in ['editor','pager','fzf-preview']:
        check(['tool',f],'str','string')
    # extra values strings
    extra,exists=get_path(['extra'])
    if exists and isinstance(extra,dict):
        for k,v in extra.items():
            if not isinstance(v,str):
                err_for(['extra',k],'string',v)
