            if isinstance(gval,dict):
                if 'paths' in gval:
                    v=gval['paths']
                    if not isinstance(v,list): err_for(['group',gname,'paths'],'[]string(slice)',v)
                    for el in v:
                        if not isinstance(el,str): err_for(['group',gname,'paths'],'string',el)
                # note sub
                if 'note' in gval and isinstance(gval['note'],dict):
                    # validate same as note fields locally - reuse positions key reconstruction
                    for f in ['language','default-title','filename','extension','template','id-charset','id-case']:
                        p=['group',gname,'note',f]
                        val,ex=get_path(p)
                        if ex and not isinstance(val,str): err_for(p,'string',val)
                    p=['group',gname,'note','id-length']; val,ex=get_path(p)
                    if ex and (not isinstance(val,int) or isinstance(val,bool)): err_for(p,'int',val)
                if 'extra' in gval and isinstance(gval['extra'],dict):
                    for k,v in gval['extra'].items():
                        if not isinstance(v,str): err_for(['group',gname,'extra',k],'string',v)

def load_config_file(path, err_prefix_kind):
    # returns parsed data dict or None if missing/non-file
    if not path or not os.path.isfile(path):
        return None
    try:
        text=pathlib.Path(path).read_text(encoding='utf-8')
    except Exception as e:
        return None
    try:
        parsed=parse_toml(text)
        _validate_config(parsed)
        return parsed.data
    except TomlError as e:
        if err_prefix_kind=='global':
            raise AppError(f"initialization: failed to read config: {e}")
        elif err_prefix_kind=='local':
            raise AppError(f"failed to open notebook: failed to read config: {e}")
        else:
            raise

def build_config(global_data, local_data=None):
    cfg=_deep_copy(DEFAULTS)
    if global_data: _merge(cfg, global_data)
    if local_data: _merge(cfg, local_data)
    return cfg

# ---------- Date / human relative ----------
def relative_time(tv):
    now=TimeValue.now()
    diff_sec=(now.epoch_ns-tv.epoch_ns)/1e9
    if diff_sec<0:
        return "not yet"
    sec=int(diff_sec)
    if sec<60:
        return "just now"
    minutes=sec//60
    if minutes<60:
        return f"{minutes} {plural('minute',minutes)} ago"
    hours=minutes//60
    if hours<24:
        return f"{hours} {plural('hour',hours)} ago"
    days=hours//24
    if days==1:
        return "yesterday"
    if days<7:
        return f"{days} days ago"
    if days<22:
        weeks=(days+6)//7
        return f"{weeks} {plural('week',weeks)} ago"
    if days<331:
        months=(days+29)//30
        if months>=12:
            years=(days+364)//365
            return f"{years} {plural('year',years)} ago"
        return f"{months} {plural('month',months)} ago"
    years=(days+364)//365
    return f"{years} {plural('year',years)} ago"

