# ---------- Filtering / sorting ----------
def _convert_path_arg(nb, arg):
    # returns (rel, abs, original)
    # clean abs
    if os.path.isabs(arg):
        abs_path=os.path.normpath(arg)
    else:
        abs_path=os.path.normpath(os.path.join(nb.working_dir, arg)) if arg!="" else os.path.normpath(nb.working_dir)
        if arg=="":
            abs_path=os.path.normpath(nb.working_dir)
    # "" cleaned to working dir -> rel "."
    rel=go_relpath(nb.root, abs_path)
    return rel, abs_path

def _match_path_rel(note_rel, arg_rel, nb):
    if arg_rel is None: return False
    if arg_rel=='.':
        return '/' not in note_rel
    if arg_rel=='..' or arg_rel.startswith('../'):
        return False
    # file exact or stem
    if note_rel==arg_rel: return True
    if _stem_of_path(note_rel)==arg_rel: return True
    # dir prefix
    if note_rel.startswith(arg_rel.rstrip('/')+'/'): return True
    return False

def _resolve_path_args(nb, args, all_notes, discard_outside=True, original_for_error=False):
    # returns list of notes matching
    rel_args=[]
    originals=[]
    for a in args:
        rel,abs_path=_convert_path_arg(nb, a)
        if discard_outside and (rel=='..' or rel.startswith('../')):
            continue
        rel_args.append(rel); originals.append(a)
    if not rel_args:
        return [], rel_args, originals
    matched=[]
    seen=set()
    for n in all_notes:
        for rel in rel_args:
            if _match_path_rel(n._root_rel, rel, nb):
                if n.id not in seen:
                    matched.append(n); seen.add(n.id)
                break
    return matched, rel_args, originals

def _glob_match(pattern, value):
    # pattern with * and ? as wildcard
