    # Path positional filter
    if criteria.paths:
        # convert & discard outside
        rel_args=[]
        for a in criteria.paths:
            rel,_=_convert_path_arg(nb,a)
            if rel=='..' or rel.startswith('../'): continue
            rel_args.append(rel)
        if rel_args:
            result=[n for n in result if any(_match_path_rel(n._root_rel, rel, nb) for rel in rel_args)]
