        mentioned_by_sources=resolve_or_error(criteria.mentioned_by, discard_outside=False)

    def bfs(start_ids, adjacency, max_dist, recursive):
        # returns set of ids reachable with distance >=1 and (distance==1 if not recursive else distance<=max_dist or unlimited)
        if not recursive:
            found=set()
            for s in start_ids:
                for tgt in adjacency.get(s,[]):
                    found.add(tgt)
            return found
        # recursive
        limit=max_dist if max_dist and max_dist>0 else None
        found=set()
        visited_dist={s:0 for s in start_ids}
        frontier=list(start_ids)
        dist=0
        while frontier:
            dist+=1
            if limit is not None and dist>limit: break
            nxt=[]
            for cur in frontier:
                for tgt in adjacency.get(cur,[]):
                    if tgt not in visited_dist or visited_dist[tgt]>dist:
                        # allow revisiting start nodes at distance>0
                        if tgt not in found:
                            found.add(tgt); nxt.append(tgt)
                        visited_dist[tgt]=dist
                    elif tgt in start_ids and tgt not in found:
                        found.add(tgt)
