    if criteria.no_link_to and link_targets.get('no_link_to'):
        target_ids=[n.id for n in link_targets['no_link_to']]
        found=bfs(target_ids, in_edges, 1, False)  # direct only? no-link respects max/rec? original probably direct complement; use same logic as link-to but complement of direct? Test later
        # For no-link, likely they invert link-to filter with same recursive settings. We'll compute with same params as link
        found2=bfs(target_ids, in_edges, criteria.max_distance, criteria.recursive)
        result=[n for n in result if n.id not in found2]
