        result=[n for n in result if mentions(n)]
    if criteria.mentioned_by and mentioned_by_sources:
        source_ids=set(n.id for n in mentioned_by_sources)
        hays=[(n.title+"\n"+n.body).lower() for n in mentioned_by_sources]
        def mentioned(note):
