        result=[n for n in result if mentioned(n)]
    if criteria.related and link_targets.get('related'):
        target_ids=set(n.id for n in link_targets['related'])
        # direct neighbors both directions
        direct=set()
        for tid in target_ids:
            direct.update(out_edges.get(tid,[])); direct.update(in_edges.get(tid,[]))
        candidates=set()
        for tid in target_ids:
            # forward 2 steps
            for mid in out_edges.get(tid,[]):
                for r in out_edges.get(mid,[]):
                    candidates.add(r)
            # backward 2 steps: R -> mid -> tid
            for mid in in_edges.get(tid,[]):
                for r in in_edges.get(mid,[]):
                    candidates.add(r)
        candidates-=target_ids
        candidates-=direct
        result=[n for n in result if n.id in candidates]
    # Date filters
    if criteria.date_filters:
        df=criteria.date_filters
        def date_ok(n):
            if 'created_eq' in df and not _date_filter_match(n.created, df['created_eq'],'eq'): return False
            if 'created_before' in df and not _date_filter_match(n.created, df['created_before'],'before'): return False
            if 'created_after' in df and not _date_filter_match(n.created, df['created_after'],'after'): return False
            if 'modified_eq' in df and not _date_filter_match(n.modified, df['modified_eq'],'eq'): return False
            if 'modified_before' in df and not _date_filter_match(n.modified, df['modified_before'],'before'): return False
            if 'modified_after' in df and not _date_filter_match(n.modified, df['modified_after'],'after'): return False
            return True
        result=[n for n in result if date_ok(n)]
    # Match filtering
    fts_rank={}
    fts_snippet={}
    if criteria.match:
        # clean empty queries
        queries=[q for q in criteria.match if q!='']
        if queries:
            if criteria.match_strategy=='fts':
                con=nb.open_db()
                combined=' '.join(queries)
                try:
                    rows=con.execute("SELECT n.id, snippet(notes_fts, 2, '', '', '…', 20), rank FROM notes n JOIN notes_fts ON notes_fts.rowid=n.id WHERE notes_fts MATCH ? ", (combined,)).fetchall()
                    # SQLite rank ordering later; store
                    match_ids=set()
                    for nid,snip,rank in rows:
                        match_ids.add(nid); fts_snippet[nid]=snip; fts_rank[nid]=rank
                    result=[n for n in result if n.id in match_ids]
                    for n in result:
                        snip=fts_snippet.get(n.id,'')
                        n.snippets=[snip] if snip else []
