                    criteria._fts_rank=fts_rank
                except sqlite3.Error:
                    result=[]
                    for n in result: n.snippets=[n.lead] if n.lead else []
            elif criteria.match_strategy=='exact':
                def exact_match(note):
                    raw=note.raw_content.lower()
                    for q in queries:
                        if q.lower() not in raw: return False
                    return True
                result=[n for n in result if exact_match(n)]
            elif criteria.match_strategy=='re':
                patterns=[]
                valid=True
                for q in queries:
                    try: patterns.append(re.compile(q))
                    except re.error: valid=False
                if not valid:
                    result=[]
                else:
                    def re_match(note):
                        for pat in patterns:
                            if not pat.search(note.raw_content): return False
                        return True
                    result=[n for n in result if re_match(n)]
