    if criteria.sort_terms:
        result=sort_notes(result, criteria.sort_terms)
    else:
        if criteria.match and criteria.match_strategy=='fts' and hasattr(criteria,'_fts_order'):
            order=criteria._fts_order
            result=sorted(result, key=lambda n: order.get(n.id, 999999))
        else:
            result=sort_notes(result, [])
    if criteria.limit and criteria.limit>0:
        result=result[:criteria.limit]
    return result

