    charset_name=group_note_cfg.get('id-charset','alphanum')
    length=group_note_cfg.get('id-length',4)
    try: length=int(length)
    except: length=4
    if length<0: length=0
    case=group_note_cfg.get('id-case','lower')
    if charset_name=='letters': chars='abcdefghijklmnopqrstuvwxyz'
    elif charset_name=='numbers': chars='0123456789'
    elif charset_name=='alphanum': chars='abcdefghijklmnopqrstuvwxyz0123456789'
    elif charset_name=='hex': chars='0123456789abcdef'
    else: chars=str(charset_name)
    if case=='mixed':
        # For known sets, include both cases for letters
        if charset_name in ('letters','alphanum'):
            chars=chars+chars.upper()
