def _note_config_for_group(nb, directory_rel, explicit_group):
    base_note=dict(nb.config.get('note',{}))
    base_extra=dict(nb.config.get('extra',{}))
    groups=nb.config.get('group',{}) or {}
    chosen=None
    if explicit_group:
        if explicit_group not in groups:
            raise AppError(f"new note: no group named `{explicit_group}` found in the config")
        chosen=groups[explicit_group]
    else:
        # directory match: paths default to [group name]
        best=None; best_len=-1
        for gname,gcfg in groups.items():
            if not isinstance(gcfg,dict): continue
            paths=gcfg.get('paths')
            if paths is None: paths=[gname]
            for p in paths:
                p_clean=p.strip('/')
                if directory_rel==p_clean or (p_clean and directory_rel.startswith(p_clean+'/')) or p_clean=='' :
                    if len(p_clean)>best_len:
                        best=gcfg; best_len=len(p_clean)
        chosen=best
    if chosen and isinstance(chosen,dict):
        if isinstance(chosen.get('note'),dict):
            base_note.update(chosen['note'])
        if isinstance(chosen.get('extra'),dict):
            base_extra.update(chosen['extra'])
    return base_note, base_extra

