            working_dir=clean_abs(parsed.flags.get('working-dir'),cwd) if parsed.flags.get('working-dir') else cwd
            starter=clean_abs(parsed.flags.get('notebook-dir'),cwd) if parsed.flags.get('notebook-dir') else (clean_abs(os.environ.get("ZK_NOTEBOOK_DIR",""),cwd) if os.environ.get("ZK_NOTEBOOK_DIR","") else working_dir)
