                return cmd_index(parsed, nb)
            if parsed.command=='new':
                return cmd_new(parsed, nb)
            if parsed.command in ('list','graph'):
                return cmd_list(parsed, nb, command=parsed.command)
            if parsed.command=='edit':
                return cmd_edit(parsed, nb)
            if parsed.command=='tag':
                return cmd_tag_list(parsed, nb)
        finally:
