    except FatalMessage as e:
        sys.stderr.write(f"zk: {e}\n"); return 1
    except AppError as e:
        sys.stderr.write(error_text(str(e))); return 1
    except TemplateFatal as e:
        sys.stderr.write(f"zk: {e}\n"); return 1
    except BrokenPipeError:
        try: sys.stdout.close()
        except: pass
        return 0
    except KeyboardInterrupt:
        return 130
    return 0

