                if 'date' in opts: synth.flags['date']=opts.get('date') or ''
                # extra: dict to list k=v
                extra_dict=opts.get('extra') if isinstance(opts.get('extra'),dict) else {}
                synth.flags['extra']=[f"{k}={v}" for k,v in extra_dict.items()]
                content_opt=opts.get('content') or ''
            else:
                content_opt=''
            dry=bool(opts.get('dryRun')) if isinstance(opts,dict) else False
