def _lsp_type_name_go(v):
    if isinstance(v,str): return 'string'
    if isinstance(v,bool): return 'bool'
    if isinstance(v,(int,float)): return 'float64' if isinstance(v,float) else 'int'
    if isinstance(v,list): return '[]interface {}'
    if isinstance(v,dict): return 'map[string]interface {}'
    return type(v).__name__

def _lsp_list_type_check(opts):
    fields={'select':('[]string','list'),'sort':('[]string','list'),'limit':('int','int'),'match':('[]string','list'),'matchStrategy':('string','str'),'tags':('[]string','list'),'mention':('[]string','list'),'mentionedBy':('[]string','list'),'linkTo':('[]string','list'),'linkedBy':('[]string','list'),'related':('[]string','list'),'hrefs':('[]string','list'),'orphan':('bool','bool'),'tagless':('bool','bool'),'missingBacklink':('bool','bool'),'maxDistance':('int','int'),'recursive':('bool','bool'),'created':('string','str'),'createdBefore':('string','str'),'createdAfter':('string','str'),'modified':('string','str'),'modifiedBefore':('string','str'),'modifiedAfter':('string','str')}
    for k,(gotype,pytype) in fields.items():
        if k not in opts: continue
        v=opts[k]; ok=True
        if pytype=='list': ok=isinstance(v,list)
        elif pytype=='str': ok=isinstance(v,str)
        elif pytype=='int': ok=isinstance(v,int) and not isinstance(v,bool)
        elif pytype=='bool': ok=isinstance(v,bool)
        if not ok:
            actual='object' if isinstance(v,dict) else ('array' if isinstance(v,list) else _lsp_type_name_go(v))
            return f"failed to parse zk.list args, got: {_go_repr(opts)}: json: cannot unmarshal {actual} into Go struct field cmdListOpts.Filtering.{k} of type {gotype}" if k!='select' else f"failed to parse zk.list args, got: {_go_repr(opts)}: json: cannot unmarshal {actual} into Go struct field cmdListOpts.select of type []string"
    return None

def _lsp_new_type_check(opts):
    for k in ['title','dir','content','group','date','template']:
        if k in opts and not isinstance(opts[k],str):
            v=opts[k]; actual='object' if isinstance(v,dict) else ('array' if isinstance(v,list) else _lsp_type_name_go(v))
            return f"failed to parse zk.new args, got: {_go_repr(opts)}: json: cannot unmarshal {actual} into Go struct field cmdNewOpts.{k} of type string"
    if 'extra' in opts:
        if not isinstance(opts['extra'],dict):
            return f"failed to parse zk.new args, got: {_go_repr(opts)}: json: cannot unmarshal {_lsp_type_name_go(opts['extra'])} into Go struct field cmdNewOpts.extra of type string"
        for kk,vv in opts['extra'].items():
            if not isinstance(vv,str):
                return f"failed to parse zk.new args, got: {_go_repr(opts)}: json: cannot unmarshal number into Go struct field cmdNewOpts.extra of type string" if isinstance(vv,(int,float)) else f"failed to parse zk.new args, got: {_go_repr(opts)}: json: cannot unmarshal {_lsp_type_name_go(vv)} into Go struct field cmdNewOpts.extra of type string"
    if 'dryRun' in opts and not isinstance(opts['dryRun'],bool):
        return f"failed to parse zk.new args, got: {_go_repr(opts)}: {_go_repr(opts['dryRun'])}: failed to unmarshal as boolean" if not isinstance(opts['dryRun'],dict) else f"failed to parse zk.new args, got: {_go_repr(opts)}: {json.dumps(opts['dryRun'],separators=(',',':'))}: failed to unmarshal as boolean"
    return None

def _lsp_create_note(nb, synth, content_opt, dry):
    # Reuse cmd_new by setting up parsed object and capturing outputs.
    # Build ParsedCLI-like
    parsed=type('P',(),{})(); parsed.command='new'; parsed.args=synth.args; parsed.flags=_default_flags('new'); parsed.visited=set(synth.visited if hasattr(synth,'visited') else set())
    for k,v in synth.flags.items(): parsed.flags[k]=v
    parsed.flags['dry-run']=False; parsed.flags['print-path']=False; parsed.flags['interactive']=False
    # Directory handling is same as cmd_new except content source comes from opts and no editor stage.
    # Temporarily use cmd_new logic duplicated minimally:
    # Date
    date_flag=parsed.flags.get('date',''); now_ref=TimeValue.now()
    if date_flag:
        tv,err=parse_human_date(date_flag, now_ref)
        if err is not None: raise AppError(err)
        if tv is not None: now_ref=tv
    working_dir=nb.working_dir
    dir_arg=parsed.args[0] if parsed.args else None
    if dir_arg is not None:
        dir_display=dir_arg; dir_abs=clean_abs(dir_arg, working_dir)
    else:
        dir_display=working_dir; dir_abs=working_dir
    if not is_subpath(dir_abs, nb.root):
        raise AppError(f"new note: {dir_display if dir_arg else dir_abs}: path is outside the notebook at {nb.root}")
    if not os.path.isdir(dir_abs):
        raise AppError(f"new note: {dir_display}: directory not found")
    dir_rel=go_relpath(nb.root, dir_abs)
    if dir_rel=='.': dir_rel=''
    explicit_group=parsed.flags.get('group','') or ''
    note_cfg, extra_cfg=_note_config_for_group(nb, dir_rel, explicit_group)
    title=parsed.flags.get('title','') or (note_cfg.get('default-title','Untitled') or 'Untitled')
    extras=dict(extra_cfg)
    for el in parsed.flags.get('extra',[]):
        if '=' in el:
            k,v=el.split('=',1); extras[k]=v
    note_id=_generate_id(nb, note_cfg)
    env_context={'id':note_id,'title':title,'content':content_opt,'now':now_ref,'extra':extras,'env':dict(os.environ),'filename':'','path':''}
    render_env=RenderEnv(warn_func=lambda m: warn_raw(m), slug_language=note_cfg.get('language','en'), now_ref=TimeValue.now(), style_enabled=False)
